import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { Chat } from 'chat';
import { createTelegramAdapter } from '@chat-adapter/telegram';
import { createMemoryState } from '@chat-adapter/state-memory';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Volter Harness's Telegram channel: the Chat SDK's adapter from TELEGRAM_BOT_TOKEN, polling (sdk/orchestrator/adapters/chat-sdk.mjs)
const telegram = createTelegramAdapter({ botToken: process.env.TELEGRAM_BOT_TOKEN, mode: 'polling', logger: console });
const receiptFile = 'telegram-chat.json';
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  const thread = await telegram.fetchThread(saved.thread);
  assert.equal(thread.id, saved.thread);
  assert.equal(thread.isDM, true);
  assert.equal(thread.metadata.chat.first_name, 'Ada');
  console.log(JSON.stringify({ retained: true, thread: thread.id, chat: thread.metadata.chat }));
} else {
  // Ada opens the bot in the Telegram app and writes to it: the World's doors stand in for the app
  const api = (process.env.TELEGRAM_API_BASE_URL ?? 'https://api.telegram.org').replace(/\/+$/, '');
  const door = async (path, body) => {
    const response = await fetch(api + path, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) });
    if (!response.ok) throw new Error(path + ' was refused: ' + response.status + ' ' + await response.text());
    return response.json();
  };
  const ada = await door('/_twin/people', { first_name: 'Ada', username: 'ada_lovelace' });
  await door('/_twin/messages', { from: ada.id, chat: '@' + process.env.TELEGRAM_BOT_USERNAME, text: 'Hi! Can you keep notes of our standups?' });
  const answered = new Promise((resolve, reject) => {
    const chat = new Chat({ adapters: { telegram }, state: createMemoryState(), concurrency: 'concurrent', logger: 'silent' });
    chat.onDirectMessage(async (thread, message) => {
      try {
        const sent = await thread.post('Noted, Ada: I will keep the standup notes here.');
        resolve({ chat, thread, message, sent });
      } catch (error) { reject(error); }
    });
    chat.initialize().catch(reject);
  });
  const { chat, thread, message, sent } = await answered;
  await telegram.stopPolling();
  await chat.shutdown();
  assert.equal(thread.isDM, true);
  assert.equal(message.text, 'Hi! Can you keep notes of our standups?');
  assert.equal(message.author.userId, String(ada.id));
  assert.equal(message.author.isMe, false);
  assert.equal(thread.id, 'telegram:' + ada.id);
  assert.match(String(sent.id), new RegExp('^' + ada.id + ':\\d+$'), 'the answer names the message Telegram gave it in her chat');
  assert.equal(sent.text, 'Noted, Ada: I will keep the standup notes here.');
  writeFileSync(receiptFile, JSON.stringify({ thread: thread.id, message: sent.id }) + '\n');
  console.log(JSON.stringify({ answered: true, thread: thread.id, heard: message.text, sent: sent.id }));
}
